namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = new();

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
        : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Stretch dough into a circle.\n3. Spread crushed tomatoes.\n4. Add torn mozzarella.\n5. Bake 10-12 minutes.\n6. Top with fresh basil and olive oil."
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Season with black pepper."
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or broil chicken pieces.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and garam masala.\n5. Simmer, add cream.\n6. Add chicken and cook 10 minutes."
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs",
            Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, pan-fry until golden.\n3. Scramble eggs in wok.\n4. Add noodles and sauce (tamarind, fish sauce, sugar).\n5. Toss with bean sprouts.\n6. Serve with peanuts and lime."
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Cumin, Chili powder",
            Steps = "1. Brown ground beef with cumin and chili powder.\n2. Warm taco shells.\n3. Dice tomato and shred lettuce.\n4. Assemble tacos with beef, lettuce, tomato.\n5. Top with cheese and sour cream."
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Salt, Tomato",
            Steps = "1. Halve and pit avocados.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato.\n4. Add lime juice and cilantro.\n5. Season with salt."
        },
        new Recipe
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Green curry paste, Coconut milk, Chicken, Bamboo shoots, Thai basil, Fish sauce, Sugar",
            Steps = "1. Heat coconut cream until oil separates.\n2. Fry curry paste until fragrant.\n3. Add chicken, cook through.\n4. Pour in coconut milk.\n5. Add bamboo shoots, fish sauce, sugar.\n6. Finish with Thai basil."
        },
        new Recipe
        {
            Id = 8, Title = "Dal Tadka", Category = "Indian",
            Ingredients = "Yellow lentils, Tomatoes, Onion, Garlic, Cumin seeds, Turmeric, Ghee, Cilantro",
            Steps = "1. Boil lentils with turmeric until soft.\n2. Sauté onion and tomatoes.\n3. Combine with lentils and simmer.\n4. In ghee, fry cumin seeds and garlic (tadka).\n5. Pour tadka over dal.\n6. Garnish with cilantro."
        }
    };

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}

