arguments.file_text:
@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>

<div class="row">
    @foreach (var category in Categories)
    {
        <div class="col-md-3 mb-4">
            <div class="card h-100">
                <div class="card-body text-center">
                    <h5 class="card-title">@category</h5>
                    <a href="/recipes/@category.ToLower()" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories { get; set; } = Array.Empty<string>();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/recipes/{Category}"

<PageTitle>@Category Recipes - RecipeShare</PageTitle>

<h1>@Category Recipes</h1>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.Ratings.Count > 0)
                            {
                                <span>⭐ @recipe.AverageRating / 5 (@recipe.Ratings.Count ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeShare.Services.Recipe> Recipes { get; set; } = Array.Empty<RecipeShare.Services.Recipe>();

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

@if (Recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@Recipe.Category</span>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in Recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var text = step.Contains('.') ? step[(step.IndexOf('.') + 1)..].Trim() : step;
            <li>@text</li>
        }
    </ol>

    <h3>Rate this Recipe</h3>
    <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.Ratings.Count" />

    <a href="/recipes/@Recipe.Category.ToLower()" class="btn btn-secondary mt-4">← Back to @Recipe.Category Recipes</a>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Services.Recipe? Recipe { get; set; }

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div class="star-rating my-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= DisplayRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              role="button"
              title="Rate @star stars">
            @(star <= DisplayRating ? "★" : "☆")
        </span>
    }
    <span class="ms-2 text-muted">
        @if (RatingCount > 0)
        {
            @($"{CurrentRating:F1} / 5 ({RatingCount} ratings)")
        }
        else
        {
            @("No ratings yet — be the first!")
        }
    </span>
    @if (Submitted)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

<style>
    .star-rating .star {
        font-size: 1.5rem;
        cursor: pointer;
        color: #ccc;
        transition: color 0.15s;
    }
    .star-rating .star.filled {
        color: #f5a623;
    }
</style>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private int HoverRating { get; set; }
    private bool Submitted { get; set; }

    private int DisplayRating => HoverRating > 0 ? HoverRating : (int)Math.Round(CurrentRating);

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.Ratings.Count;
        }
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmitSuccess)
{
    <div class="alert alert-success">
